from textual.app import ComposeResult, App
from textual.widgets import Button, Container
from textual.message import Message


class MyWidget(Container):
    """A widget that sends a custom message."""

    class MyCustomMessage(Message):
        """A custom message sent from MyWidget to its parent."""
        def __init__(self, text: str) -> None:
            super().__init__()
            self.text = text

    def compose(self) -> ComposeResult:
        yield Button("Send Message", id="send_button")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Handle button press by sending custom message to parent."""
        self.post_message(self.MyCustomMessage("Message from MyWidget"))


class MyApp(App):
    """Main application."""

    def compose(self) -> ComposeResult:
        yield MyWidget()

    def on_my_custom_message(self, message: MyWidget.MyCustomMessage) -> None:
        """Handle the custom message from MyWidget."""
        self.title = f"Received: {message.text}"


if __name__ == "__main__":
    MyApp().run()

